Translate("zhCN", "valley-of-strength", {
	title = "力量谷",
	sections = {
		{
			title = "概述",
			text = [=[力量谷就在{link:orgrimmar}奥格瑞玛{/link}的大门之内。它是城里最繁忙的地方。这里有银行、拍卖行和酒馆，它们上方是双足飞龙降落的塔楼。步兵守望着每一条道路。来自{link:horde}部落{/link}各个民族的旅行者挤满了它的道路，来自整个{link:kalimdor}卡利姆多{/link}的消息都经过这里。部落也在这里庆祝它的胜利。被击败的敌人的首级被高高挂在{link:stranglethorn-vale}山谷{/link}上方，城市的霸王们号召人民向夺取它们的英雄致敬。]=],
