		{
			title = "概述",
			text = [=[暗影裂口是{link:orgrimmar}奥格瑞玛{/link}中心的一道幽暗峡谷，阳光很少能照到那里。它是盗贼、术士和制毒者的街区。术士{link:neeru-fireblade}尼尔鲁·火刃{/link}在这里搭着他的帐篷，碎手也在这里秘密集会。在裂口的底部，有一条通道向下通往{link:ragefire-chasm}怒焰裂谷{/link}。城里的老实人避开暗影裂口，而住在那里的人也乐得如此。大酋长的许多秘密都保存在这里，他的一些敌人的秘密也是如此。]=],
		},
	},
})

Translate("zhCN", "valley-of-honor", {
	title = "荣誉谷",
	sections = {
		{
			title = "概述",
			text = [=[荣誉谷位于{link:orgrimmar}奥格瑞玛{/link}的东北部，属于{link:horde}部落{/link}的战士。在勇士大厅里，老兵们教年轻人使用斧子和盾牌的方法。猎人在这里有他们的小屋，城里铁匠的锻炉日夜燃烧。{link:stranglethorn-vale}山谷{/link}中回荡着铁锤的叮当声和对练者的呼喊声。一个想被称为战士的{link:orcs}兽人{/link}，会来这里证明自己。]=],
		},
	},
})

Translate("zhCN", "valley-of-spirits", {
	title = "精神谷",
	sections = {
		{
			title = "概述",
			text = [=[精神谷沿着{link:orgrimmar}奥格瑞玛{/link}的西南部延伸。它是{link:darkspear-trolls}暗矛巨魔{/link}的街区。他们的小屋矗立在{link:orcs}兽人{/link}的建筑之间，他们的巫医、牧师和法师在这里践行部族古老的传统。年轻的{link:trolls}巨魔{/link}牧师在这座{link:stranglethorn-vale}山谷{/link}中被引入长者的圈子。它平静的水池倒映着上方的红色岩壁。在城中所有的山谷里，它是最安静的，巨魔们也让它保持这样。暗矛在这里怀念他们失去的岛屿。]=],
		},
	},
