Translate("zhCN", "valley-of-wisdom", {
	title = "智慧谷",
	sections = {
		{
			title = "概述",
			text = [=[智慧谷位于{link:orgrimmar}奥格瑞玛{/link}的西北部，远离大门的喧嚣。它是大酋长的所在。{link:stranglethorn-vale}山谷{/link}的尽头耸立着{link:grommash-hold}格罗姆什要塞{/link}，{link:horde}部落{/link}的萨满祭司聚集在它周围，像他们的祖先在德拉诺时那样，教年轻人与{link:elements}元素{/link}交谈。城里的长者来这里提供建议，也听取建议。这是一个学习之地，也是一个权力之地。许多寻求大酋长青睐的人都走过它的道路。]=],
		},
	},
