Translate("zhCN", "grommash-hold", {
	title = "格罗姆什要塞",
	sections = {
		{
			title = "概述",
			text = [=[格罗姆什要塞是大酋长的堡垒，建在{link:valley-of-wisdom}智慧谷{/link}的悬崖之中。它以{link:grom-hellscream}格罗姆·地狱咆哮{/link}的名字命名，他的牺牲使{link:orcs}兽人{/link}摆脱了恶魔之血。它的大厅宽广而昏暗，由火光照亮。在大厅的尽头，{link:thrall}萨尔{/link}坐在他的王座上理政。{link:darkspear-trolls}暗矛{/link}的{link:vol-jin}沃金{/link}站在他的身旁，还有老战士{link:eitrigg}伊崔格{/link}和先知{link:zor-lonetree}佐尔·孤树{/link}。库卡隆精英卫兵把守着大门，未经他们允许，任何人都不得来到大酋长面前。]=],
